    Status status_{ State::Stopped, 0, 0, 0, 0 };
};

solution.solution.cpp:
#include <cstdint>
#include <stdexcept>

enum class State : std::uint32_t { Stopped = 1, StartPending, StopPending, Running, ContinuePending, PausePending, Paused };
constexpr std::uint32_t ACCEPT_STOP = 1, ACCEPT_PAUSE_CONTINUE = 2, ACCEPT_SHUTDOWN = 4;
constexpr std::uint32_t CONTROL_STOP = 1, CONTROL_PAUSE = 2, CONTROL_CONTINUE = 3, CONTROL_INTERROGATE = 4, CONTROL_SHUTDOWN = 5;
constexpr std::uint32_t NO_ERROR_CODE = 0, ERROR_CALL_NOT_IMPLEMENTED = 120;

struct Status { State state; std::uint32_t controlsAccepted; std::uint32_t checkPoint; std::uint32_t waitHint; std::uint32_t exitCode; };

class ServiceReporter
{
public:
    explicit ServiceReporter(bool canPause) : canPause_{ canPause } {}

    Status report(State state, std::uint32_t waitHint = 0, std::uint32_t exitCode = 0)
    {
        if (!allowed(status_.state, state)) throw std::logic_error("this state change is not allowed");
        const bool pending{ isPending(state) };
        if (pending && waitHint == 0) throw std::invalid_argument("a pending state needs a wait hint");
        Status next{};
        next.state = state;
        next.checkPoint = pending ? status_.checkPoint + 1 : 0;
        next.waitHint = pending ? waitHint : 0;
        next.exitCode = state == State::Stopped ? exitCode : 0;
        if (state == State::Running || state == State::Paused)
            next.controlsAccepted = ACCEPT_STOP | ACCEPT_SHUTDOWN | (canPause_ ? ACCEPT_PAUSE_CONTINUE : 0);
        status_ = next;
        return status_;
    }

    std::uint32_t handle(std::uint32_t control)
    {
        const std::uint32_t accepted{ status_.controlsAccepted };
        switch (control)
        {
        case CONTROL_INTERROGATE:
            return NO_ERROR_CODE;
        case CONTROL_STOP:
        case CONTROL_SHUTDOWN:
            if (!(accepted & (control == CONTROL_STOP ? ACCEPT_STOP : ACCEPT_SHUTDOWN))) return ERROR_CALL_NOT_IMPLEMENTED;
            report(State::StopPending, 5000);
            return NO_ERROR_CODE;
        case CONTROL_PAUSE:
            if (!(accepted & ACCEPT_PAUSE_CONTINUE) || status_.state != State::Running) return ERROR_CALL_NOT_IMPLEMENTED;
            report(State::PausePending, 2000);
            return NO_ERROR_CODE;
        case CONTROL_CONTINUE:
            if (!(accepted & ACCEPT_PAUSE_CONTINUE) || status_.state != State::Paused) return ERROR_CALL_NOT_IMPLEMENTED;
            report(State::ContinuePending, 2000);
            return NO_ERROR_CODE;
        default:
            return ERROR_CALL_NOT_IMPLEMENTED;
        }
    }

    const Status& current() const { return status_; }

private:
    static bool isPending(State s)
    {
        return s == State::StartPending || s == State::StopPending || s == State::PausePending || s == State::ContinuePending;
    }

    static bool allowed(State from, State to)
    {
        switch (from)
        {
        case State::Stopped: return to == State::StartPending;
        case State::StartPending: return to == State::StartPending || to == State::Running || to == State::Stopped;
        case State::Running: return to == State::StopPending || to == State::PausePending;
        case State::PausePending: return to == State::PausePending || to == State::Paused;
        case State::Paused: return to == State::ContinuePending || to == State::StopPending;
        case State::ContinuePending: return to == State::ContinuePending || to == State::Running;
        case State::StopPending: return to == State::StopPending || to == State::Stopped;
        }
        return false;
    }

    bool canPause_;
    Status status_{ State::Stopped, 0, 0, 0, 0 };
};

unitTests:
bool is(const Status& s, State state, std::uint32_t accepted, std::uint32_t checkPoint, std::uint32_t waitHint, std::uint32_t exitCode = 0) {
    return s.state == state && s.controlsAccepted == accepted && s.checkPoint == checkPoint && s.waitHint == waitHint && s.exitCode == exitCode;
}
TEST("starting with progress reports") {
    ServiceReporter r{ false };
    CHECK(is(r.report(State::StartPending, 3000), State::StartPending, 0, 1, 3000));
    CHECK(is(r.report(State::StartPending, 3000), State::StartPending, 0, 2, 3000));
    CHECK(is(r.report(State::Running), State::Running, ACCEPT_STOP | ACCEPT_SHUTDOWN, 0, 0));
}
TEST("stopping through a control") {
    ServiceReporter r{ false };
    r.report(State::StartPending, 1000);
    r.report(State::Running, 999);
    CHECK_EQ(r.current().waitHint, 0u);
    CHECK_EQ(r.handle(CONTROL_INTERROGATE), NO_ERROR_CODE);
    CHECK_EQ(r.current().state, State::Running);
    CHECK_EQ(r.handle(CONTROL_PAUSE), ERROR_CALL_NOT_IMPLEMENTED);
    CHECK_EQ(r.handle(CONTROL_STOP), NO_ERROR_CODE);
    CHECK(is(r.current(), State::StopPending, 0, 1, 5000));
    CHECK_EQ(r.handle(CONTROL_STOP), ERROR_CALL_NOT_IMPLEMENTED);
    CHECK(is(r.report(State::StopPending, 5000), State::StopPending, 0, 2, 5000));
    CHECK(is(r.report(State::Stopped, 0, 0), State::Stopped, 0, 0, 0));
}
TEST("pausing and continuing") {
    ServiceReporter r{ true };
    r.report(State::StartPending, 1000);
    CHECK_EQ(r.report(State::Running).controlsAccepted, ACCEPT_STOP | ACCEPT_SHUTDOWN | ACCEPT_PAUSE_CONTINUE);
    CHECK_EQ(r.handle(CONTROL_CONTINUE), ERROR_CALL_NOT_IMPLEMENTED);
    CHECK_EQ(r.handle(CONTROL_PAUSE), NO_ERROR_CODE);
    CHECK(is(r.current(), State::PausePending, 0, 1, 2000));
    r.report(State::Paused);
    CHECK_EQ(r.handle(CONTROL_CONTINUE), NO_ERROR_CODE);
    CHECK(is(r.current(), State::ContinuePending, 0, 1, 2000));
    r.report(State::Running);
    CHECK_EQ(r.handle(CONTROL_SHUTDOWN), NO_ERROR_CODE);
    CHECK_EQ(r.current().state, State::StopPending);
}
TEST("a failed start") {
    ServiceReporter r{ false };
    r.report(State::StartPending, 1000);
    CHECK(is(r.report(State::Stopped, 0, 1067), State::Stopped, 0, 0, 0, 1067));
    CHECK_EQ(r.report(State::StartPending, 1000).checkPoint, 1u);
}
TEST("refused reports change nothing") {
    ServiceReporter r{ false };
    CHECK_THROWS_AS(r.report(State::Running), std::logic_error);
    CHECK_THROWS_AS(r.report(State::StartPending, 0), std::invalid_argument);
    CHECK_EQ(r.current().state, State::Stopped);
    r.report(State::StartPending, 100);
    CHECK_THROWS_AS(r.report(State::Paused), std::logic_error);
    CHECK_THROWS_AS(r.report(State::StartPending), std::invalid_argument);
    CHECK(is(r.current(), State::StartPending, 0, 1, 100));
    CHECK_EQ(r.report(State::Running, 0, 55).exitCode, 0u);
    CHECK_EQ(r.handle(99), ERROR_CALL_NOT_IMPLEMENTED);
}

